@Component("costCenter-handler")
@ProcessingGroup("costCenter-processing-group")
public class CostCenterEventHandler {
	
	// core constructor
	CostCenterEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCostCenterEvent
     */
    @EventHandler
    public void handle( CreateCostCenterEvent event) {
        entityManager.persist(new CostCenter(event.getCostCenterId(), event.getCode(), event.getName(), event.getOrganization(), event.getDepartments(), event.getPositions(), event.getEmployees()));
    }

    /*
     * @param	event UpdateCostCenterEvent
     */
    @EventHandler
    public CostCenter handle( UpdateCostCenterEvent event) {
    	entityManager.merge(new CostCenter(event.getCostCenterId(), event.getCode(), event.getName(), event.getOrganization(), event.getDepartments(), event.getPositions(), event.getEmployees()));
    }
    
    /*
     * @param	event DeleteCostCenterEvent
     */
    @EventHandler
    public void on( DeleteCostCenterEvent event) {
    	CostCenter entity = new CostCenter();
   
    	// ------------------------------------------
    	// apply the CostCenterId
    	// ------------------------------------------
    	entity.setCostCenterId( event.getCostCenterId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CostCenterRepository costCenterEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CostCenterEventHandler.class.getName());

}
